html=html.replace('</body>',patch+'\n<script id="v130-marker">window.__todayCodiV130=true;</script>\n</body>',1)
required=['v1.3.0 · 큰 글씨','v1.3.0 · 아바타+','__todayCodiV130PreviewMatched','v130Home','v130LookStage','추천 룩','v130-bottom','__todayCodiV1100OutfitModelNoFaceMerge','__todayCodiV111PreciseLocation']
